  return {
    name,
    instrumented,
    buildArgs: instrumented
      ? ["--workspace", "--locked"]
      : ["--workspace", "--exclude", "mesh-talk", "--locked"],
    partitions: instrumented ? windowsPartitions : [1, 2],
    testThreads: instrumented ? 1 : 4,
